      issues.push({
        field: 'profile',
        severity: 'warning',
        message: `Profile only ${Math.round(profileCompleteness * 100)}% complete`
      });
    }
    
    return {
      valid: !issues.some(i => i.severity === 'error'),
      issues
    };
