class RealTimeDashboardService {
  // Live campaign metrics
  async getLiveCampaignMetrics(
    campaignId: UUID
  ): Promise<LiveCampaignMetrics> {
    const cacheKey = `campaign:${campaignId}:live`;
    
    // Check cache first
    const cached = await this.redis.get(cacheKey);
    if (cached) {
