      { name: 'VIP Customer', contact: this.createTestContact({ lifecycle: 'vip', lifetimeValue: 50000000 }) },
      { name: 'Inactive User', contact: this.createTestContact({ lastActivity: subtractDays(new Date(), 90) }) }
    ];
    
