class TastefulPersonalizationService {
  async personalizeContent(
    contact: Contact,
    content: ContentTemplate
  ): Promise<PersonalizedContent> {
    // Only use data that adds value
    const personalizationData = {
      // ✅ Good: Obvious value-adds
